package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_siblingNodes_TriageGen0Test {

    @Test
    public void testSiblingNodesWithMultipleChildren() {
        // Setup a document structure: <div><p></p><span></span></body></div>
        String html = "<div><p></p><span></span></div>";
        Document doc = Parser.parseChunk(html, "");
        Element div = doc.child(0);
        Element p = div.child(0);
        Element span = div.child(1);

        // Execute
        List<Node> siblings = p.siblingNodes();

        // Verify
        // siblingNodes() returns parent().childNodes(), which includes the node itself and its siblings
        Assert.assertEquals(2, siblings.size());
        Assert.assertTrue(siblings.contains(p));
        Assert.assertTrue(siblings.contains(span));
    }

    @Test
    public void testSiblingNodesWithSingleChild() {
        String html = "<div><p></p></div>";
        Document doc = Parser.parseChunk(html, "");
        Element div = doc.child(0);
        Element p = div.child(0);

        List<Node> siblings = p.siblingNodes();

        Assert.assertEquals(1, siblings.size());
        Assert.assertEquals(p, siblings.get(0));
    }

    @Test
    public void testSiblingNodesWithNoChildren() {
        // Testing a node that is a leaf/empty inside a parent
        String html = "<div><p></p></div>";
        Document doc = Parser.parseChunk(html, "");
        Element div = doc.child(0);
        Element p = div.child(0);
        p.text(""); // Ensure it's empty but exists

        List<Node> siblings = p.siblingNodes();

        Assert.assertNotNull(siblings);
        Assert.assertEquals(1, siblings.size());
    }

    @Test(expected = NullPointerException.class)
    public void testSiblingNodesWhenNoParent() {
        // A node with no parent should throw NullPointerException when calling parent().childNodes()
        Element orphan = new Element("", "");

        // This should trigger parent() returning null, then null.childNodes()
        orphan.siblingNodes();
    }

    @Test
    public void testSiblingNodesOrder() {
        String html = "<ul><li>1</li><li>2</li><li>3</li></ul>";
        Document doc = Parser.parseChunk(html, "");
        Element ul = doc.child(0);
        Element li2 = ul.child(1);

        List<Node> siblings = li2.siblingNodes();

        Assert.assertEquals(3, siblings.size());
        Assert.assertEquals(ul.child(0), siblings.get(0));
        Assert.assertEquals(ul.child(1), siblings.get(1));
        Assert.assertEquals(ul.child(2), siblings.get(2));
    }
}
